{"Channel": {"name": "planning-PersonalizeForce-PM", "channelID": "ch-ix-pm-1c1e2c"}, "Message": {"User": {"userId": "eid_a9002ae2", "timestamp": "2026-05-19T17:28:00", "text": "The detailed analytics dashboard sounds like a great feature for tracking user engagement. Do you know if it offers any predictive analytics capabilities?", "utterranceID": "20260724-7-1e0b1"}, "Reactions": []}, "ThreadReplies": [], "id": "20260724-7-1e0b1"}
