{"Channel": {"name": "bug-iansmith-TrendForce", "channelID": "ch-force-c56b63"}, "Message": {"User": {"userId": "eid_82e9fcef", "timestamp": "2026-07-18T22:13:00", "text": "Hi team, several customers are reporting issues with TrendForce that need our attention. Let's go through them one by one. 😊", "utterranceID": "20260718-0-5f44d"}, "Reactions": []}, "ThreadReplies": [], "id": "20260718-0-5f44d"}
