{"Channel": {"name": "bug-iansmith-CollaborationForce", "channelID": "ch-force-f8518f"}, "Message": {"User": {"userId": "eid_82e9fcef", "timestamp": "2026-10-28T14:48:00", "text": "Hi team, several customers are reporting issues with CollaborationForce that need our attention. Let's go through them one by one. 😊", "utterranceID": "20261028-0-ef598"}, "Reactions": []}, "ThreadReplies": [], "id": "20261028-0-ef598"}
