{"Channel": {"name": "planning-ProposalBuilder", "channelID": "ch-ilder-ebf3c2"}, "Message": {"User": {"userId": "eid_b48f959b", "timestamp": "2026-12-26T23:16:00", "text": "Hi team, I want to discuss the Technical Specifications Document for ProposalBuilder. Let's brainstorm some ideas and outline the key sections we need to include. 😊", "utterranceID": "20261226-0-2c46e"}, "Reactions": []}, "ThreadReplies": [], "id": "20261226-0-2c46e"}
