{"Channel": {"name": "bug-alicemartinez-ConnectForce", "channelID": "ch-force-c583cf"}, "Message": {"User": {"userId": "eid_294ba09d", "timestamp": "2026-07-23T00:32:00", "text": "Hi team, I've found some interesting open-source bugs that might help us with our current Salesforce issues. Let's take a look! 😊", "utterranceID": "20260722-0-704ea"}, "Reactions": []}, "ThreadReplies": [], "id": "20260722-0-704ea"}
