{"Channel": {"name": "bug-alicetaylor-MonitorForce", "channelID": "ch-force-7ef125"}, "Message": {"User": {"userId": "eid_641eee2a", "timestamp": "2026-08-04T01:53:00", "text": "Hi team, I looked into the reported issue about the UI Element Overlap where critical alert notifications overlap with other UI elements.", "utterranceID": "20260803-0-6bb94"}, "Reactions": []}, "ThreadReplies": [], "id": "20260803-0-6bb94"}
