{"Channel": {"name": "bug-juliataylor-ContextForce", "channelID": "ch-force-3aa08e"}, "Message": {"User": {"userId": "eid_14a5889d", "timestamp": "2027-03-20T12:16:00", "text": "Thanks for the update, @eid_ecaa9084. Did you verify if this setting impacts any critical functionality for our partners?", "utterranceID": "20270320-4-a1631"}, "Reactions": []}, "ThreadReplies": [], "id": "20270320-4-a1631"}
